create table users(id uuid primary key, email text not null unique, password text not null, name varchar(60) not null, role text not null default 'MEMBER', public_score boolean not null default false, restricted boolean not null default false);
create table quiz(id uuid primary key, slug text unique not null, published boolean not null default false, featured boolean not null default false, current_edition uuid);
create table edition(id uuid primary key, quiz_id uuid not null references quiz, number int not null, content text not null, created_at timestamptz not null default now(), unique(quiz_id,number));
alter table quiz add foreign key(current_edition) references edition;
create table attempt(id uuid primary key, edition_id uuid not null references edition, user_id uuid references users, guest_key text, ranked boolean not null, answers text, result text, started_at timestamptz not null default now(), finished_at timestamptz, check(user_id is not null or guest_key is not null));
create table leaderboard(id uuid primary key, edition_id uuid not null references edition, user_id uuid not null references users, score int not null, maximum int not null, achieved_at timestamptz not null default now(), hidden boolean not null default false, reason text, unique(edition_id,user_id));
create table submission(id uuid primary key, user_id uuid not null references users, revision int not null default 1, status text not null, kind text not null, target_id uuid references quiz, content text not null, submitted_at timestamptz, note text, published_id uuid references edition);
create table submission_revision(id uuid primary key, submission_id uuid not null references submission, revision int not null, content text not null, unique(submission_id,revision));
create table review(id uuid primary key, submission_id uuid not null references submission, revision int not null, reviewer uuid not null references users, decision text not null, note text, created_at timestamptz not null default now(), edition_id uuid references edition);
create table question_bank(id uuid primary key, submission_id uuid unique not null references submission, target_id uuid references quiz, content text not null, published_id uuid references edition);
create table report(id uuid primary key, quiz_id uuid not null references quiz, reason text not null, resolved boolean not null default false, created_at timestamptz not null default now());
create table moderation(id uuid primary key, owner_id uuid references users, user_id uuid references users, reason text not null, created_at timestamptz not null default now());
create table reset_token(token_hash text primary key, user_id uuid not null references users, expires_at timestamptz not null);
create table profile(code varchar(4) primary key, content text not null);
create table metric(name text primary key, value bigint not null default 0);
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL, SESSION_ID CHAR(36) NOT NULL, CREATION_TIME BIGINT NOT NULL, LAST_ACCESS_TIME BIGINT NOT NULL, MAX_INACTIVE_INTERVAL INT NOT NULL, EXPIRY_TIME BIGINT NOT NULL, PRINCIPAL_NAME VARCHAR(100), CONSTRAINT SPRING_SESSION_PK PRIMARY KEY (PRIMARY_ID));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION (SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION (EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION (PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES (SESSION_PRIMARY_ID CHAR(36) NOT NULL, ATTRIBUTE_NAME VARCHAR(200) NOT NULL, ATTRIBUTE_BYTES BYTEA NOT NULL, CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY (SESSION_PRIMARY_ID, ATTRIBUTE_NAME), CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY (SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
